const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(n);
export function schedule(principal,annualRate,months,firstDate){if(![principal,annualRate,months].every(Number.isFinite)||principal<0||annualRate<0||months<1||months>600||!Number.isInteger(months))throw Error('Check the loan amount, interest and number of months.');if(principal===0)return [];const r=annualRate/1200,emi=r?principal*r/(-Math.expm1(-months*Math.log1p(r))):principal/months;const parts=firstDate?.split('-').map(Number);let balance=principal;const rows=[];for(let i=0;i<months;i++){const interest=balance*r,payment=i===months-1?balance+interest:emi,paid=payment-interest;balance=Math.max(0,balance-paid);let date='Not set';if(parts?.length===3&&parts.every(Number.isFinite)){const [year,month,day]=parts;const lastDay=new Date(Date.UTC(year,month+i,0)).getUTCDate();date=new Date(Date.UTC(year,month-1+i,Math.min(day,lastDay))).toISOString().slice(0,10);}rows.push({instalment:i+1,date,payment,interest,principal:paid,balance});}return rows;}
export function fundingGap(setup,own,loan){if([setup,own,loan].some(x=>!Number.isFinite(x)||x<0))throw Error('Funding amounts must be non-negative.');return {neededLoan:Math.max(0,setup-own),gap:Math.max(0,setup-own-loan),surplus:Math.max(0,own+loan-setup)};}
export function initFunding(){const block=document.createElement('div');block.className='funding-inputs';block.innerHTML=`<h3>How will you pay for the business?</h3><div class="fields"><label>Total money needed to start (₹)<input name="setup" id="setup-cost" type="number" min="0" step="0.01" value="50000" required></label><label>Your own money you will invest (₹)<input name="own" id="own-money" type="number" min="0" step="0.01" value="50000" required></label><label>Where will the loan come from?<select id="loan-source"><option>Not decided yet</option><option>Bank / Regional Rural Bank</option><option>Cooperative bank / credit society</option><option>Self-help group (SHG)</option><option>NBFC / microfinance lender</option><option>Family / friends</option><option>Other lender</option></select></label><label>Lender / bank name (optional)<input id="lender-name" maxlength="100" placeholder="Enter the actual bank or lender"></label><label>Date of first monthly instalment (optional)<input id="first-payment" type="date"></label></div><p class="muted">Include equipment, starting stock and a cash reserve in the total startup cost. Enter the loan and annual interest quoted by your lender below. No lender or interest rate is automatically recommended.</p>`;$('finance').querySelector('.fields').before(block);const out=document.createElement('section');out.id='funding-roadmap';out.className='panel funding-roadmap';$('wizard-page-5').insertBefore(out,$('wizard-page-5').querySelector('.next-section'));}
export function fundingData(inputs){const gap=fundingGap(inputs.setup,inputs.own,inputs.principal);return {...gap,setup:inputs.setup,own:inputs.own,loan:inputs.principal,source:inputs.principal>0?$('loan-source').value:'No loan',lender:$('lender-name').value,firstPayment:$('first-payment').value,annualRate:inputs.rate,instalments:inputs.principal>0?inputs.months:0,schedule:schedule(inputs.principal,inputs.rate,inputs.months,$('first-payment').value)};}
export function renderFunding(inputs,result){const data=fundingData(inputs);const out=$('funding-roadmap');out.replaceChildren();const title=document.createElement('h3');title.textContent='Your financial roadmap';out.append(title);const summary=document.createElement('p');summary.className='funding-summary';summary.textContent=`Startup cost ${money(data.setup)} · your investment ${money(data.own)} · loan ${money(data.loan)}. ${data.gap>0?'Still to arrange: '+money(data.gap):data.surplus>0?'Money above startup estimate: '+money(data.surplus):'Your planned funds cover the startup estimate.'}`;out.append(summary);const lender=document.createElement('p');lender.textContent=data.loan>0?`Loan source: ${data.source}${data.lender?' — '+data.lender:''}. ${data.instalments} monthly instalments at ${inputs.rate}% annual interest. Estimated EMI ${money(result.emi)}; total interest ${money(result.interest)}; total repayment ${money(result.total)}.`:'You have planned no loan. There are no loan instalments or interest payments.';out.append(lender);const ol=document.createElement('ol');for(const line of ['Before starting: get local cost quotes and confirm the amount of your own savings you can use.',data.loan>0?'Before borrowing: compare written offers from your chosen bank, cooperative, SHG or other lender. Check interest calculation, fees, collateral and the full repayment schedule. Approval is decided by the lender.':'Start with the available own funds; resolve any funding gap before buying.',data.loan>0?`Each month: set aside ${money(result.emi)} for the loan. Based on your business assumptions, cash after EMI is ${money(result.cash)} per month.`:'Each month: record sales and expenses and keep money for restocking.',result.cash<0?'Your estimated business cash after EMI is negative. Reduce costs, revise the business plan or loan size before committing.':'Review actual sales and costs every month and keep a reserve for slower months.']){const li=document.createElement('li');li.textContent=line;ol.append(li);}out.append(ol);if(data.schedule.length){const details=document.createElement('details'),head=document.createElement('summary');head.textContent='See every monthly instalment';details.append(head);const wrap=document.createElement('div');wrap.className='schedule-scroll';const table=document.createElement('table');table.innerHTML='<thead><tr><th>No.</th><th>Due date</th><th>Instalment</th><th>Interest</th><th>Loan repaid</th><th>Balance</th></tr></thead>';const body=document.createElement('tbody');for(const row of data.schedule){const tr=document.createElement('tr');for(const value of [row.instalment,row.date,money(row.payment),money(row.interest),money(row.principal),money(row.balance)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}body.append(tr);}table.append(body);wrap.append(table);details.append(wrap);out.append(details);}const note=document.createElement('p');note.className='muted';note.textContent='Schedule assumes a fixed annual rate, monthly reducing-balance interest and no fees, moratorium or missed payments. Family, SHG or flat-rate loans may use different terms. Confirm the actual schedule with the lender. Dates are estimates based on the first instalment date you enter.';out.append(note);}
